\newcommand{\Z}{\mathbb{Z}}
\newcommand{\hint}{\mathrm{hint}}

\title[The hint is universal exactly at odd moduli]{The Hint Is Universal Exactly at Odd Moduli:\\
Two-Torsion Floors, Ceilings and the Independence of Capacity and Hint}
\author{Aristotle}
\date{September 25, 2026}

\begin{document}

\begin{abstract}
Take a finite population of samples. Each sample carries a pair $(P,Q)$ of elements of a finite commutative ring $R$ and a label $T$. There are two natural ways to summarise the pair: by its product $N=PQ$, or by its sum and difference $(s,d)=(P+Q,P-Q)$. The \emph{hint value} $\hint=I(T;(s,d))-I(T;N)$ is the amount, in bits of empirical mutual information, by which the sum/difference reading beats the product reading at predicting the label. A six-dial experiment reported positive hint values at the moduli $11,5,31,23,8,9$ and gave the verdict ``the hint is universal''. We determine exactly when this verdict holds. The main tool is a \emph{two-torsion floor}: if some map into a finite set $F$ separates any two ring elements with the same double, then $\hint\ge-\log_2|F|$. Consequently the hint is nonnegative in every ring without $2$-torsion, and in particular over $\Z/n$ for odd $n$. Over $\Z/n$ with $n$ even the hint is at least $-1$ bit, and $-1$ is attained at every even $n$. So every battery over $\Z/n$ has nonnegative hint if and only if $n$ is odd. Over $\Z/2k\times\Z/2l$ the floor is $-2$ bits, attained over $\Z/8\times\Z/8$. We also prove the ceiling $\hint\le 2\log_2 n$, the budget $I(T;N)+\hint\le H(T)$ and the coupling floor $\hint\ge-I(T;N)$. Finally we show that capacity and hint are functionally independent: over $\Z/5$ they attain all four points of $\{0,1\}^2$.
\end{abstract}

\maketitle

\section{Introduction}

Each sample is a pair of residues $(P,Q)$ modulo $m$ with a label. We compare the \emph{product reading} $N=PQ \bmod m$, whose informativeness about the label is the \emph{capacity}, with the \emph{sum/difference reading} $(s,d)=(P+Q,P-Q)\bmod m$. Over a field of characteristic other than $2$ we can recover $P=(s+d)/2$ and $Q=(s-d)/2$. The product is then a function of $(s,d)$, and by the data-processing inequality the hint value is nonnegative.

A six-dial experiment gave the following table. Dials are named by a finite group and a modulus, and only the modulus enters the analysis.

\begin{center}
\begin{tabular}{lccc}
\toprule
dial & modulus $m$ & capacity $I(T;N)$ & hint value\\
\midrule
$C_5$ & 11 & 1.2062 & $+1.5896$\\
$F_{20}$ & 5 & 0.2920 & $+0.9538$\\
$S_3$ (a) & 31 & 1.0011 & $+0.5201$\\
$S_3$ (b) & 23 & 1.0008 & $+0.5121$\\
$D_4$ & 8 & 1.9999 & $+0.5032$\\
$A_4$ & 9 & 0.0015 & $+0.0120$\\
\bottomrule
\end{tabular}
\end{center}

The total hint is $4.0908$ bits, the total capacity is $5.5015$ bits, and the Pearson correlation between capacity and hint is $r\approx0.256$. We turn the two claims drawn from this table, universality and independence, into theorems with exact scope.

\section{Definitions and toolkit}

\begin{definition}[Battery]
A \emph{battery} over a commutative ring $R$ consists of a finite nonempty set $\Omega$ of samples, a label map $T:\Omega\to\Lambda$ into an arbitrary set, and coordinate maps $P,Q:\Omega\to R$. Probabilities refer to the uniform distribution on $\Omega$.
\end{definition}

\begin{definition}[Readings]
A \emph{reading} is any map on $\Omega$. We use three:
\begin{itemize}
\item the product reading $N=PQ$;
\item the residue reading $\rho=(P+Q,P-Q)\in R^2$;
\item the pair reading $\pi=(P,Q)\in R^2$.
\end{itemize}
$H(f)$ denotes the Shannon entropy in bits of the pushforward of the uniform distribution under $f$. The mutual information is $I(T;f)=H(T)+H(f)-H(T,f)$.
\end{definition}

\begin{definition}[Capacity and hint value]
The \emph{capacity} of a battery is $I(T;N)$. Its \emph{hint value} is $\hint(T,P,Q)=I(T;\rho)-I(T;N)$.
\end{definition}

We use the following standard facts.
\begin{itemize}
\item[(F1)] $0\le I(T;f)\le H(T)$.
\item[(F2)] $I(T;f)\le H(f)\le\log_2|\mathcal A|$ if $f$ takes values in a finite set $\mathcal A$.
\item[(F3)] Data processing: $I(T;\phi\circ f)\le I(T;f)$ for any function $\phi$.
\item[(F4)] If $f$ determines $T$ then $I(T;f)=H(T)$. If $T$ determines $f$ then $I(T;f)=H(f)$.
\item[(F5)] A constant reading has zero information.
\end{itemize}

\begin{lemma}[Refinement bound]\label{lem:refine}
Let $f,g$ be readings and let $e:\Omega\to F$ take values in a finite set $F$. Assume that $f$ determines $g$ and that $(g,e)$ determines $f$. Then $I(T;f)\le I(T;g)+\log_2|F|$.
\end{lemma}
\begin{proof}[Proof sketch]
By (F3) and the chain rule,
\[
I(T;f)\le I(T;(g,e))=I(T;g)+I(T;e\mid g)\le I(T;g)+H(e)\le I(T;g)+\log_2|F|. \qedhere
\]
\end{proof}

\section{The two-torsion floor}

\begin{definition}[Torsion selector]
A \emph{two-torsion selector} for $R$ with values in a finite set $F$ is a map $\sigma:R\to F$ such that
\[
2a=2b \ \text{ and } \ \sigma(a)=\sigma(b) \ \Longrightarrow\ a=b .
\]
\end{definition}

\begin{theorem}[Product-versus-residue bound]\label{thm:floor}
For every battery over $R$ and every two-torsion selector $\sigma:R\to F$,
\[
I(T;N)\le I(T;\rho)+\log_2|F|.
\]
\end{theorem}
\begin{proof}
Apply Lemma~\ref{lem:refine} with $f=\pi$, $g=\rho$ and $e=\sigma\circ P$. The pair determines $\rho$. Conversely, equal residue readings give $2P(x)=s+d=2P(y)$. Equal selector values then give $P(x)=P(y)$, and hence $Q(x)=s-P(x)=Q(y)$. Finally, $N$ is a function of $\pi$, so (F3) applies.
\end{proof}

\begin{corollary}[Two-torsion floor]
$\hint(T,P,Q)\ge-\log_2|F|$ whenever $R$ admits a two-torsion selector into $F$.
\end{corollary}

\begin{corollary}[Two-torsion-free rings]\label{cor:tf}
If $2a=0$ implies $a=0$ in $R$, then every battery over $R$ has $\hint\ge0$.
\end{corollary}
\begin{proof}
The constant map into a one-point set is a selector, and $\log_2 1=0$.
\end{proof}

\section{Cyclic moduli: the odd/even dichotomy}

\begin{theorem}[Odd moduli]\label{thm:odd}
For odd $n$, every battery over $\Z/n$ has nonnegative hint value.
\end{theorem}
\begin{proof}
The element $2$ is a unit in $\Z/n$, so the ring has no nonzero $2$-torsion. Apply Corollary~\ref{cor:tf}.
\end{proof}

\begin{definition}[Half-range selector]
For $k\ge1$ let $\eta(a)=[\bar a<k]$ on $\Z/2k$, where $\bar a\in\{0,\dots,2k-1\}$ is the least nonnegative representative of $a$.
\end{definition}

\begin{lemma}\label{lem:half}
$\eta$ is a two-torsion selector with two values.
\end{lemma}
\begin{proof}
If $2\bar a\equiv2\bar b\pmod{2k}$ then $\bar a\equiv\bar b\pmod k$, so $\bar a$ and $\bar b$ are equal or differ by $k$. If they lie in the same half, they are equal.
\end{proof}

\begin{theorem}[One-bit floor]\label{thm:even}
For even $n$, every battery over $\Z/n$ satisfies $\hint\ge-1$.
\end{theorem}

\begin{lemma}[Collision mechanism]\label{lem:coll}
Consider a two-sample battery with distinct labels whose samples have the same residue reading but different products. Its hint value is exactly $-1$.
\end{lemma}
\begin{proof}
The residue reading is constant, so $I(T;\rho)=0$. The product determines the label, so $I(T;N)=H(T)=1$.
\end{proof}

\begin{theorem}[Attainment at every even modulus]\label{thm:attain}
For every $k\ge1$ there is a two-sample battery over $\Z/2k$ with hint value $-1$:
\begin{itemize}
\item if $k$ is even, the samples $(0,1)$ and $(k,k+1)$;
\item if $k$ is odd, the samples $(0,0)$ and $(k,k)$.
\end{itemize}
\end{theorem}
\begin{proof}
In the first case both samples have $s=1$ and $d=-1$, and the products are $0$ and $k(k+1)$. If $2k\mid k(k+1)$ then $k+1$ is even, which is impossible. In the second case both samples have $s=0$ and $d=0$, and the products are $0$ and $k^2$. If $2k\mid k^2$ then $k$ is even, which is impossible. Lemma~\ref{lem:coll} finishes the proof.
\end{proof}

\begin{example}
Modulo $8$, the samples $(0,1)$ and $(4,5)$ share $(s,d)=(1,7)$ and have products $0$ and $4$. Modulo $6$, the samples $(0,0)$ and $(3,3)$ share $(s,d)=(0,0)$ and have products $0$ and $3$.
\end{example}

\begin{theorem}[The hint is universal exactly at odd moduli]
For $n\ge1$ the following are equivalent:
\begin{enumerate}
\item every battery over $\Z/n$ has nonnegative hint;
\item every two-sample, two-label battery over $\Z/n$ has nonnegative hint;
\item $n$ is odd.
\end{enumerate}
For even $n$ the infimum of the hint is exactly $-1$, and it is attained.
\end{theorem}
\begin{proof}
Combine Theorems~\ref{thm:odd}, \ref{thm:even} and~\ref{thm:attain}.
\end{proof}

\section{Products of even rings}

\begin{lemma}[Selectors multiply]
If $\sigma_i$ is a selector for $R_i$ with values in $F_i$ for $i=1,2$, then $(a_1,a_2)\mapsto(\sigma_1(a_1),\sigma_2(a_2))$ is a selector for $R_1\times R_2$ with values in $F_1\times F_2$.
\end{lemma}

\begin{theorem}[Two-factor floor]
Every battery over $\Z/2k\times\Z/2l$ has $\hint\ge-2$.
\end{theorem}

\begin{theorem}[Attainment]
Over $\Z/8\times\Z/8$, take four samples with
\[
P=(0,0),(0,4),(4,0),(4,4),\qquad Q=(1,1),(1,5),(5,1),(5,5)
\]
and four distinct labels. This battery has hint value exactly $-2$.
\end{theorem}
\begin{proof}
All four samples have $s=(1,1)$ and $d=(7,7)$, so $I(T;\rho)=0$. The products $(0,0),(0,4),(4,0),(4,4)$ are distinct, so $I(T;N)=\log_2 4=2$.
\end{proof}

\section{Ceiling, budget and coupling}

\begin{theorem}[Modulus ceiling]
Over $\Z/n$, $\hint\le I(T;\rho)\le H(\rho)\le2\log_2 n$.
\end{theorem}

\begin{proposition}[Budget]
$I(T;N)+\hint=I(T;\rho)\le H(T)$.
\end{proposition}

\begin{proposition}[Coupling floor]
$\hint\ge-I(T;N)$. Hence at an even modulus, $\hint\ge-\min(1,I(T;N))$.
\end{proposition}

\section{Capacity and hint are functionally independent}

\begin{theorem}[Four corners]
Over $\Z/5$, with four samples and labels in a four-element set, the pair $(I(T;N),\hint)$ attains $(0,0)$, $(0,1)$, $(1,0)$ and $(1,1)$.
\end{theorem}
\begin{proof}
Let $W$ have samples $(1,1),(1,2),(2,3),(2,1)$. Its residue readings $(2,0),(3,4),(0,4),(3,1)$ are distinct, and its products are $1,2,1,2$. Let $C$ have samples $(1,1),(1,1),(1,2),(1,2)$.
\begin{center}
\begin{tabular}{cccccc}
\toprule
corner & battery & labels & $I(T;N)$ & $I(T;\rho)$ & hint\\
\midrule
$(0,0)$ & $W$ & $0,0,0,0$ & 0 & 0 & 0\\
$(0,1)$ & $W$ & $0,0,1,1$ & 0 & 1 & 1\\
$(1,0)$ & $C$ & $0,0,1,1$ & 1 & 1 & 0\\
$(1,1)$ & $W$ & $0,1,2,3$ & 1 & 2 & 1\\
\bottomrule
\end{tabular}
\end{center}
For the corner $(0,1)$: the label partition $\{0,1\}|\{2,3\}$ and the product partition $\{0,2\}|\{1,3\}$ are independent, and the residue reading is injective. The other rows follow from (F1) and (F4).
\end{proof}

\begin{corollary}
The hint is not a function of the capacity, and the capacity is not a function of the hint.
\end{corollary}

\begin{remark}
The only constraints linking the two coordinates are the budget and the floors. ``Independent'' means functional independence subject to a joint budget, not statistical independence.
\end{remark}

\section{The six-dial table}

\begin{theorem}[Dial windows]
\leavevmode
\begin{enumerate}
\item For $m\in\{11,5,31,23,9\}$, every battery over $\Z/m$ satisfies $0\le\hint\le2\log_2 m$.
\item Every battery over $\Z/8$ satisfies $-1\le\hint$, $-I(T;N)\le\hint$ and $\hint\le6$.
\item The value $-1$ is attained over $\Z/8$.
\end{enumerate}
\end{theorem}

The reported columns sum to $4.0908$ (hint) and $5.5015$ (capacity), and each reported hint lies in its window. With $\mathrm{cov}(u,v)=\sum_i(u_i-\bar u)(v_i-\bar v)$ we get
\[
\mathrm{cov}(c,h)=\tfrac{48451189}{10^8},\quad \mathrm{cov}(c,c)=\tfrac{299900341}{1.2\times10^8},\quad \mathrm{cov}(h,h)=\tfrac{71677991}{5\times10^7},
\]
so $0.255<r<0.257$ and $r^2<0.07$.

For the five odd dials, positivity is a law. For $D_4$ at $m=8$, the value $+0.5032$ is a property of the particular battery measured.

\section{Algorithms}

\begin{itemize}
\item \emph{Empirical hint value.} Tabulate the frequencies of $T$, $N$, $(s,d)$, $(T,N)$ and $(T,s,d)$ and combine the resulting entropies. This takes $O(n)$ time for $n$ samples.
\item \emph{Collision witness at $m=2k$.} Output $(0,1),(k,k+1)$ if $k$ is even and $(0,0),(k,k)$ if $k$ is odd. This takes $O(1)$ time.
\item \emph{Selector check.} Group the elements of $R$ by their double and test injectivity of $\sigma$ on each group. This takes $O(|R|)$ time.
\item \emph{Exhaustive two-sample floor.} Search all of $(\Z/n)^4$ in $O(n^4)$ time. The minimum is $0$ for odd $n$ and $-1$ for even $n$.
\end{itemize}

\section{Discussion: the geometry of the fold}

The map $(P,Q)\mapsto(s,d)$ on the discrete torus $(\Z/m)^2$ has determinant $-2$. At odd $m$ it is a bijection, and it carries the hyperbolas $PQ=N$ to the conics $s^2-d^2=4N$. At even $m$ it folds the torus along cosets of $\{(t,t):t\in R[2]\}$. Along such a coset the product changes by $ts+t^2$. Negative hints arise exactly from folds along which the product changes. The floor loses one bit per even cyclic factor, which mirrors the gain of one orientation bit per field factor on the ceiling side.

\section{Future directions}

\begin{conjecture}[Torsion floor law]
For every finite commutative ring $R$, the infimum of the hint equals $-\log_2|R[2]|$. Attainment amounts to the injectivity of $t\mapsto ts+t^2$ on $R[2]$ for some $s$.
\end{conjecture}

\begin{conjecture}[One negative bit per even factor]
Over $\prod_{i<k}\Z/2m_i$ the floor is exactly $-k$ bits, reached by the product of the one-factor collision batteries.
\end{conjecture}

\begin{conjecture}[Product-fibre ceiling]
Over $\Z/n$ the supremum of the hint equals $\log_2M(n)$, where $M(n)$ is the largest number of pairs sharing a product residue. For example $M(p)=2p-1$ for a prime $p$, $M(8)=20$ and $M(9)=21$.
\end{conjecture}

\begin{conjecture}[Capacity--hint region]
For an odd prime $p$ and label entropy $h$, the achievable (capacity, hint) pairs are dense in the triangle $\{c\ge0,\,t\ge0,\,c+t\le\min(h,2\log_2p)\}$.
\end{conjecture}

\section{Conclusion}

The hint value is at least $-\log_2|F|$ for any two-torsion selector into $F$. It is nonnegative exactly at odd cyclic moduli, its sharp floor at even cyclic moduli is $-1$ bit, it is bounded above by $2\log_2 m$ and by the label budget, and it is functionally independent of capacity. Five of the six dials are positive by necessity, and the sixth by circumstance.

