from collections import Counter
from math import log2
from typing import Hashable, List, Sequence, Tuple


def entropy(values: Sequence[Hashable]) -> float:
    n = len(values)
    return -sum((c / n) * log2(c / n) for c in Counter(values).values())


def mutual_information(labels: Sequence[Hashable], stat: Sequence[Hashable]) -> float:
    return max(0.0, entropy(labels) + entropy(stat) - entropy(list(zip(labels, stat))))


def hint_value(samples: List[Tuple[int, int, Hashable]], m: int) -> Tuple[float, float, float]:
    """Return (capacity, joint residue information, hint) for samples (P, Q, T) mod m."""
    T = [t for _, _, t in samples]
    N = [(p * q) % m for p, q, _ in samples]
    R = [((p + q) % m, (p - q) % m) for p, q, _ in samples]
    cap = mutual_information(T, N)
    joint = mutual_information(T, R)
    return cap, joint, joint - cap


if __name__ == "__main__":
    print(hint_value([(0, 1, "a"), (4, 5, "b")], 8))   # (1.0, 0.0, -1.0)
    print(hint_value([(1, 1, 0), (1, 2, 0), (2, 3, 1), (2, 1, 1)], 5))  # (0.0, 1.0, 1.0)

from collections import defaultdict
from math import log2
from typing import Callable, Dict, Hashable, List, Optional


def certified_floor(n: int, selector: Callable[[int], Hashable]) -> Optional[float]:
    """If `selector` separates elements of Z/n with equal doubles, return -log2 |image|."""
    by_double: Dict[int, List[int]] = defaultdict(list)
    for a in range(n):
        by_double[(2 * a) % n].append(a)
    for group in by_double.values():
        tags = [selector(a) for a in group]
        if len(set(tags)) != len(tags):
            return None
    image = {selector(a) for a in range(n)}
    return -log2(len(image)) if len(image) > 1 else 0.0


if __name__ == "__main__":
    print(certified_floor(11, lambda a: ()))            # 0.0  (odd: trivial selector)
    print(certified_floor(8, lambda a: a < 4))           # -1.0 (half-range selector)
    print(certified_floor(8, lambda a: ()))              # None (trivial selector fails)

from collections import Counter
from itertools import product
from math import log2
from typing import Hashable, Sequence


def H(v: Sequence[Hashable]) -> float:
    n = len(v)
    return -sum((c / n) * log2(c / n) for c in Counter(v).values())


def MI(T: Sequence[Hashable], X: Sequence[Hashable]) -> float:
    return max(0.0, H(T) + H(X) - H(list(zip(T, X))))


def two_sample_floor(n: int) -> float:
    """Exact minimum hint over all two-sample batteries with distinct labels mod n."""
    best = 0.0
    for p0, q0, p1, q1 in product(range(n), repeat=4):
        T = [0, 1]
        N = [(p0 * q0) % n, (p1 * q1) % n]
        R = [((p0 + q0) % n, (p0 - q0) % n), ((p1 + q1) % n, (p1 - q1) % n)]
        best = min(best, MI(T, R) - MI(T, N))
    return best


if __name__ == "__main__":
    for n in range(2, 13):
        print(n, "odd " if n % 2 else "even", round(two_sample_floor(n), 6))
